class Agriculture_pest_detection(API_base):
    """
    Detect the presence of pests in a specific agricultural field.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_field_id", "p_detection_method", "p_detection_time"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_field_id = params.get('p_field_id', None)
        if p_field_id is None:
            return self.handle_error(f"Required parameter 'p_field_id' is missing", 400)
        is_valid, error = self.validate_type(p_field_id, 'p_field_id', str)
        if not is_valid:
            return error
        
        p_detection_method = params.get('p_detection_method', "Visual")
        if p_detection_method is not None:
            is_valid, error = self.validate_type(p_detection_method, 'p_detection_method', str)
            if not is_valid:
                return error
        
        if p_detection_method is not None and p_detection_method not in ["Visual", "Sensor", "Drone"]:
            return self.handle_error(f"Parameter 'p_detection_method' not in valid enum", 400)
        
        p_detection_time = params.get('p_detection_time', None)
        if p_detection_time is not None:
            is_valid, error = self.validate_type(p_detection_time, 'p_detection_time', str)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Agriculture_pest_detection",
                "p_field_id": p_field_id,
                "p_detection_method": p_detection_method,
                "p_detection_time": p_detection_time
            }
        }

