class Epidemiology_calculate_incidence_rate(API_base):
    """
    Calculates the incidence rate of a specific disease within a given population over a specified time period.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_disease", "p_population_data"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_disease = params.get('p_disease', None)
        if p_disease is None:
            return self.handle_error(f"Required parameter 'p_disease' is missing", 400)
        is_valid, error = self.validate_type(p_disease, 'p_disease', str)
        if not is_valid:
            return error
        
        p_population_data = params.get('p_population_data', None)
        if p_population_data is None:
            return self.handle_error(f"Required parameter 'p_population_data' is missing", 400)
        is_valid, error = self.validate_type(p_population_data, 'p_population_data', dict)
        if not is_valid:
            return error
        

        p_population_size = p_population_data.get('p_population_size', None)
        if p_population_size is None:
            return self.handle_error(f"Required parameter 'p_population_size' is missing", 400)
        is_valid, error = self.validate_type(p_population_size, 'p_population_size', int)
        if not is_valid:
            return error
        
        p_time_period = p_population_data.get('p_time_period', "1 year")
        if p_time_period is not None:
            is_valid, error = self.validate_type(p_time_period, 'p_time_period', str)
            if not is_valid:
                return error
        
        if p_time_period is not None and p_time_period not in ["1 year", "2 years", "5 years", "10 years"]:
            return self.handle_error(f"Parameter 'p_time_period' not in valid enum", 400)
        
        p_region = p_population_data.get('p_region', None)
        if p_region is not None:
            is_valid, error = self.validate_type(p_region, 'p_region', str)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Epidemiology_calculate_incidence_rate",
                "p_disease": p_disease,
                "p_population_data": p_population_data
            }
        }

